<?php
use App\Models\ProductionCuringBatch;use App\Models\ProductionOrder;use App\Models\ProductionQualityInspection;use App\Models\ProductionQualityPlan;use App\Services\ProductionQualityService;use App\Support\CompanyFeatures;use function Livewire\Volt\{layout,mount,state};layout('layouts.app');
state(['context_type'=>'order','production_order_id'=>'','production_curing_batch_id'=>'','inspection_stage'=>'during_production','sample_quantity'=>'','inspected_quantity'=>'','passed_quantity'=>'','failed_quantity'=>'','corrective_action'=>'','retest_required'=>false,'notes'=>'','answers'=>[],'supersedes_inspection_id'=>null]);
mount(function(){abort_unless(CompanyFeatures::manufacturingEnabled()&&auth()->user()?->can('production.perform_quality_inspections'),403);if(request()->integer('retest')){$old=ProductionQualityInspection::query()->forCurrentCompany()->accessibleTo(auth()->user())->findOrFail(request()->integer('retest'));abort_unless(in_array($old->result,['failed','conditional'],true),422);$this->supersedes_inspection_id=$old->id;$this->context_type=$old->production_curing_batch_id?'batch':'order';$this->production_order_id=(string)$old->production_order_id;$this->production_curing_batch_id=(string)$old->production_curing_batch_id;$this->inspection_stage=$old->inspection_stage;}});
$updatedContextType=function(){$this->production_order_id='';$this->production_curing_batch_id='';$this->inspection_stage=$this->context_type==='batch'?'curing':'during_production';$this->answers=[];};
$currentPlan=function(){ $context=$this->context_type==='batch'?ProductionCuringBatch::query()->forCurrentCompany()->accessibleTo(auth()->user())->find($this->production_curing_batch_id):ProductionOrder::query()->forCurrentCompany()->find($this->production_order_id);if(!$context)return null;return ProductionQualityPlan::query()->where('product_id',$context->product_id)->where('inspection_stage',$this->inspection_stage)->where('status','active')->with(['checks.unit','product'])->first();};
$save=function(){ $inspection=app(ProductionQualityService::class)->createInspection(['production_order_id'=>$this->context_type==='order'?$this->production_order_id:null,'production_curing_batch_id'=>$this->context_type==='batch'?$this->production_curing_batch_id:null,'inspection_stage'=>$this->inspection_stage,'sample_quantity'=>$this->sample_quantity,'inspected_quantity'=>$this->inspected_quantity,'passed_quantity'=>$this->passed_quantity,'failed_quantity'=>$this->failed_quantity,'corrective_action'=>$this->corrective_action,'retest_required'=>$this->retest_required,'notes'=>$this->notes,'supersedes_inspection_id'=>$this->supersedes_inspection_id],$this->answers,auth()->user());session()->flash('success','Quality inspection recorded.');$this->redirectRoute('production.quality.inspections.show',$inspection,navigate:true);};
?>
<div><x-page-header :title="$supersedes_inspection_id?'Create Retest':'Create Inspection'" description="Objective checks are evaluated on the server against the active plan snapshot." :breadcrumbs="[__('production.quality.inspections')=>route('production.quality.inspections.index'),'Create'=>null]"/><form wire:submit="save" class="space-y-5"><x-card><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="text-sm font-bold">Context<select wire:model.live="context_type" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="order">Production Order</option><option value="batch">Curing Batch</option></select></label>@if($context_type==='order')<label class="text-sm font-bold">Order<select wire:model.live="production_order_id" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">Select order</option>@foreach(ProductionOrder::query()->forCurrentCompany()->with('product')->latest('production_date')->limit(200)->get() as $o)<option value="{{$o->id}}">{{$o->order_number}} · {{$o->product?->name}}</option>@endforeach</select></label><label class="text-sm font-bold">Stage<select wire:model.live="inspection_stage" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950">@foreach(['raw_material','during_production','production_completion'] as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select></label>@else<label class="text-sm font-bold">Curing Batch<select wire:model.live="production_curing_batch_id" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">Select batch</option>@foreach(ProductionCuringBatch::query()->forCurrentCompany()->accessibleTo(auth()->user())->with('product')->latest('production_date')->limit(200)->get() as $b)<option value="{{$b->id}}">{{$b->batch_number}} · {{$b->product?->name}}</option>@endforeach</select></label><label class="text-sm font-bold">Stage<select wire:model.live="inspection_stage" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="curing">Curing</option><option value="pre_release">Pre Release</option></select></label>@endif</div></x-card>
@php($activePlan=$this->currentPlan()) @if($activePlan)<x-card><h2 class="mb-1 text-lg font-black">{{$activePlan->name}} <span class="text-sm text-slate-500">v{{$activePlan->version}}</span></h2><p class="mb-4 text-sm text-slate-500">{{$activePlan->product?->name}} · {{str($activePlan->inspection_stage)->headline()}}</p><div class="space-y-4">@foreach($activePlan->checks as $check)<div wire:key="inspection-check-{{$check->id}}" class="grid gap-3 rounded-xl border border-slate-200 p-4 md:grid-cols-4 dark:border-slate-700"><div><p class="font-black">{{$check->name}}</p><p class="text-xs text-slate-500">{{str($check->acceptance_rule)->headline()}}@if($check->critical) · Critical @endif</p></div><div>@if($check->check_type==='numeric')<x-form-input label="Actual" name="answers.{{$check->id}}.numeric_value" wire:model="answers.{{$check->id}}.numeric_value"/>@elseif($check->check_type==='yes_no')<label class="text-sm font-bold">Actual<select wire:model="answers.{{$check->id}}.boolean_value" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">Select</option><option value="1">Yes</option><option value="0">No</option></select></label>@elseif($check->check_type==='selection')<label class="text-sm font-bold">Actual<select wire:model="answers.{{$check->id}}.selected_value" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">Select</option>@foreach($check->allowed_options??[] as $v)<option value="{{$v}}">{{$v}}</option>@endforeach</select></label>@else<label class="text-sm font-bold">Actual<textarea wire:model="answers.{{$check->id}}.text_value" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"></textarea></label>@endif</div>@if($check->acceptance_rule==='manual_judgement')<label class="text-sm font-bold">Judgement<select wire:model="answers.{{$check->id}}.manual_result" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">Pending</option><option value="passed">Pass</option><option value="failed">Fail</option></select></label>@else<div class="text-sm"><p class="font-bold">Requirement</p><p>{{$check->minimum_value??'—'}} / {{$check->maximum_value??'—'}} / {{$check->target_value??'—'}} {{$check->unit?->short_name}}</p></div>@endif<label class="text-sm font-bold">Comment<textarea wire:model="answers.{{$check->id}}.inspector_comment" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"></textarea></label></div>@endforeach</div></x-card><x-card><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><x-form-input label="Sample Quantity" name="sample_quantity" wire:model="sample_quantity"/><x-form-input label="Inspected Quantity" name="inspected_quantity" wire:model="inspected_quantity"/><x-form-input label="Passed Quantity" name="passed_quantity" wire:model="passed_quantity"/><x-form-input label="Failed Quantity" name="failed_quantity" wire:model="failed_quantity"/><label class="text-sm font-bold md:col-span-2">Corrective Action<textarea wire:model="corrective_action" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"></textarea></label><label class="text-sm font-bold md:col-span-2">Notes<textarea wire:model="notes" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"></textarea></label><label class="flex items-center gap-2 text-sm font-bold"><input type="checkbox" wire:model="retest_required">Retest required</label></div></x-card><div class="flex justify-end"><button class="rounded-lg bg-build-orange px-5 py-3 font-black text-white">Record Inspection</button></div>@elseif($production_order_id||$production_curing_batch_id)<div class="rounded-xl bg-amber-50 p-4 font-bold text-amber-800">No active quality plan exists for this product and stage.</div>@endif</form></div>
